% RUN_TESTS  Cross-verification of the MATLAB/Octave implementation against the Python package
% (reference values from docs/tables/numbers.json, generated by examples/generate_all.py).
fck = 30; fcm = 38; E = 22000*(fcm/10)^0.3; fctm = 0.3*fck^(2/3); GF = 73*fcm^0.18/1000;
pass = 0; total = 0;
% 1) plain law energy
law = fh_law_mc2010_plain(fctm, GF);
total = total + 1; pass = pass + fh_check('GF area of MC2010 law [N/mm]', trapz(law.w, law.s), GF, 1e-9);
% 2) Annex L compression parameter (L.13)
c = fh_concrete('annexL', fcm, E, 4.0);
total = total + 1; pass = pass + fh_check('k (L.13) for fR1k = 4', c.kpost, 1 + 20/sqrt(82 - 8.8), 1e-12);
% 3) size effect h = 400 mm vs Python (numbers.json seH400hinge = 1.33)
H = fh_hinge(100, 400, law, fh_concrete('ec2', fcm, E), E, [], [], 500);
R = fh_response(H, 40*fctm/E*H.s/400*2, 140);
total = total + 1; pass = pass + fh_check('MOR/fct, h = 400 mm', max(R.M)/(100*400^2/6)/fctm, 1.33, 0.01);
% 4) EN 14651 forward simulation, Annex L law (numbers.json extwoBfRa = fR1)
lawB = fh_law_annexL(4.0, 3.6, fctm, E, 125, 1, 1, 4.5, true);
T = fh_en14651(lawB, fh_concrete('elastic-plastic', fcm, E), E, 4, 140);
ref = fh_read_numbers('../docs/tables/numbers.json');
total = total + 1; pass = pass + fh_check('EN14651 fR1 (Annex L law)', T.fR(1), str2double(ref.extwoBfRa), 0.01);
total = total + 1; pass = pass + fh_check('EN14651 fR3 (Annex L law)', T.fR(3), str2double(ref.extwoBfRc), 0.01);
% 5) shear (L.19)
[tau, eta] = fh_tau_RdcF(0.01, 30, 0.9*460, 0.33*3.6/1.5, 0.33*3.6);
total = total + 1; pass = pass + fh_check('tau_Rd,cF (L.19) [MPa]', tau, str2double(ref.exsevtau), 0.01);
% 6) Carpinteri et al. (2015) beam, 10 kg/m3, 2phi8, inputs B, vs Python (validation_carpinteri.json)
fc = 50.95; Ec = 22199; fct10 = 0.3*(fc - 8)^(2/3); conc10 = fh_concrete('ec2', fc, Ec);
rb = fh_rebar(12, 2*pi*16, 8, 0.999*630, 630, 206000, 0.10, 2*fct10, fct10);
H = fh_hinge(100, 200, fh_law_linear(3.7, 0.441), conc10, Ec, 100, rb, 300);
R = fh_response(H, 0.06, 150);
ok = logical(cumprod(-R.eps_top <= conc10.eps_cu & R.y0 >= 0 & R.y0 <= 200));
P = 4*(max(R.M(ok)) - 24e-6*100*200*1200^2/8)/1200/1000;
total = total + 1; pass = pass + fh_check('Carpinteri 10 kg/m3 2phi8 peak load [kN]', P, 38.5, 0.02);
[Vm] = fh_masm_sfrc(250, 440, 1320, 0.0112, 32.1, 1.0, [], false, false);
total = total + 1; pass = pass + fh_check('MASM Eq. (26) [kN]', Vm/1e3, 205.0676028573, 1e-6);
[Vs] = fh_masm_sfrc(250, 1440, 4320, 0.0101, 32.1, 1.65, [], true, false);
total = total + 1; pass = pass + fh_check('MASM + Bazant size effect, d = 1440 [kN]', Vs/1e3, 547.5380990780, 1e-6);
[Vo] = fh_masm_sfrc(250, 1440, 4320, 0.0101, 32.1, 1.65);
total = total + 1; pass = pass + fh_check('MASM + size effect + aligned fibres [kN]', Vo/1e3, 420.685971835295, 1e-6);
[Vp] = fh_punching_csct(150, 200, 1100, 38, 550, 150000, 16, 4.0, 3.5);
total = total + 1; pass = pass + fh_check('CSCT + fibres punching [kN]', Vp/1e3, 1000.9161117991, 1e-3);
[Vp0] = fh_punching_csct(150, 200, 1100, 38, 550, 150000, 16, 0, 0);
total = total + 1; pass = pass + fh_check('CSCT plain punching [kN]', Vp0/1e3, 696.6622012519, 1e-3);
fprintf('\n%d / %d checks passed\n', pass, total);
